/* 
  Comparing Comm Styles:
*/

// 1. SYNCHRONOUS (HTTP/REST)
// The 'Checkout' service pauses and waits. If 'Inventory' crashes, 'Checkout' crashes.
const result = await fetch('http://inventory-service/deduct/item123');
if (result.ok) completeCheckout();

// 2. ASYNCHRONOUS (Message Broker like RabbitMQ)
// The 'Checkout' service fires a message and instantly finishes. 
// The 'Email' service picks it up 5 seconds later.
messageBroker.publish('order_completed', { orderId: 99 });
return res.send('Order Placed!');
